  body: "#FFFFFF",
  band: "#EAF3F8",
  border: "#B7C9D6",
  text: "#203040",
};

function applyTableStyle(range, header = false) {
  range.format.wrapText = true;
  range.format.verticalAlignment = "center";
  range.format.borders = { preset: "all", style: "thin", color: colors.border };
  if (header) {
    range.format.fill = colors.navy;
    range.format.font = { bold: true, color: "#FFFFFF", size: 10 };
    range.format.horizontalAlignment = "center";
  } else {
    range.format.font = { color: colors.text, size: 10 };
