import fs from "node:fs/promises";
import { SpreadsheetFile } from "@oai/artifact-tool";
const path = process.env.DAT011_VERIFY_PATH || "D:/722/codex-tools/zhixing-data-hub/outputs/dat011/dat-011-lingxing-amazon-only-coordination-20260915.xlsx";
