applyTableStyle(sheet.getRange(`A${main.start}:I${main.start}`), true);
applyTableStyle(sheet.getRange(`A${warehouses.start}:I${warehouses.start}`), true);
applyTableStyle(sheet.getRange(`A${batches.start}:I${batches.start}`), true);
