for (const r of [warehouses.start + 1, batches.start + 1]) sheet.getRange(`A${r}:I${r}`).format.rowHeight = 30;

workbook.recalculate();
await fs.mkdir("D:/722/codex-tools/zhixing-data-hub/outputs/dat011", { recursive: true });
const output = await SpreadsheetFile.exportXlsx(workbook);
await output.save(outputPath);
const preview = await workbook.render({ sheetName: sheet.name, autoCrop: "all", scale: 1, format: "png" });
await fs.writeFile(previewPath, new Uint8Array(await preview.arrayBuffer()));

const check = await workbook.inspect({
  kind: "table",
  sheetId: sheet.name,
  range: `A1:I${batches.end}`,
  include: "values,formulas",
  tableMaxRows: batches.end,
  tableMaxCols: 9,
  tableMaxCellChars: 220,
});
console.log(check.ndjson);
