  text: "#203040",
};

function applyTableStyle(range, header = false) {
  range.format.wrapText = true;
  range.format.verticalAlignment = "center";
  range.format.borders = { preset: "all", style: "thin", color: colors.border };
  if (header) {
    range.format.fill = colors.navy;
    range.format.font = { bold: true, color: "#FFFFFF", size: 10 };
    range.format.horizontalAlignment = "center";
  } else {
    range.format.font = { color: colors.text, size: 10 };
  }
}

function writeTable(startRow, headers, rows) {
  const lastCol = String.fromCharCode(64 + headers.length);
  sheet.getRange(`A${startRow}:${lastCol}${startRow}`).values = [headers];
  if (rows.length) sheet.getRange(`A${startRow + 1}:${lastCol}${startRow + rows.length}`).values = rows;
  applyTableStyle(sheet.getRange(`A${startRow}:${lastCol}${startRow + rows.length}`));
  applyTableStyle(sheet.getRange(`A${startRow}:${lastCol}${startRow}`), true);
  for (let i = 0; i < rows.length; i += 1) {
    if (i % 2 === 1) sheet.getRange(`A${startRow + 1 + i}:${lastCol}${startRow + 1 + i}`).format.fill = colors.band;
  }
  sheet.getRange(`A${startRow + 1}:${lastCol}${startRow + rows.length}`).format.verticalAlignment = "top";
  return { start: startRow, end: startRow + rows.length };
}

function sectionTitle(row, text) {
  sheet.getRange(`A${row}:I${row}`).merge();
