    if payload.get("code") in (0, 200) or payload.get("success") is True:
        return "success"
    if any(word in low for word in ("权限", "forbidden", "unauthor")):
        return "permission_or_module"
    if any(word in low for word in ("未找到", "不存在", "not found", "no data")):
        return "not_found_or_empty"
    if any(word in low for word in ("参数", "必填", "required", "invalid", "无效")):
