            sta_item["packing_detail"] = {"category": "no_real_inbound_plan_id"}
        result["tests"]["sta_packing"] = sta_item

        # 8) Fulfillment result requires task_id returned by a prior label-submit operation.
        task_pairs = pairs(candidates, ["task_id", "taskId"], 12134)
        if task_pairs and 12134 in seller_by_sid:
            body = {"seller_id": seller_by_sid[12134], "task_id": [task_pairs[0][1]]}
            result["tests"]["fulfillment_result"] = (await call("/pb/mp/order/getFulfillmentResult", body))[0]
        else:
            result["tests"]["fulfillment_result"] = {"category": "no_real_task_id_from_label_submit"}

        # 9) Warehouse-bin recommendation: source records provide wid, while productId/fnsku
        # must come from a joined product/listing record. Report whether that join exists.
        wid_pairs = pairs(candidates, ["wid"], 12134)
        product_pairs = pairs(candidates, ["productId", "product_id"], 12134)
        fnsku_pairs = pairs(candidates, ["fnsku"], 12134)
        if not wid_pairs:
            warehouse_summary, warehouse_payload = await call(
                "/erp/sc/data/local_inventory/warehouse", {"type": 1, "is_delete": "0,1"}
            )
            warehouse_rows = rows(warehouse_payload) if isinstance(warehouse_payload, dict) else []
            wid_pairs = [
                (12134, str(first_value(row, ("wid", "warehouseId", "warehouse_id"))))
                for row in warehouse_rows if first_value(row, ("wid", "warehouseId", "warehouse_id"))
            ]
            result["tests"]["warehouse_catalog"] = warehouse_summary | {"real_wid_count": len(unique(wid_pairs))}
        if not product_pairs:
            product_pairs = live_product_ids or [
                (12134, str(first_value(row, ("productId", "product_id", "id"))))
                for row in product_rows if first_value(row, ("productId", "product_id", "id"))
            ]
        if not fnsku_pairs:
            fnsku_pairs = [
                (12134, str(first_value(row, ("fnsku", "fnSku"))))
                for row in product_rows if first_value(row, ("fnsku", "fnSku"))
            ]
        if wid_pairs and product_pairs and fnsku_pairs:
            body = {"list": [{"wid": wid_pairs[0][1], "productId": product_pairs[0][1], "fnsku": fnsku_pairs[0][1], "sid": 12134}], "withHistory": False}
            first_summary, _ = await call("/basicOpen/warehouseConfig/warehouseBin/getEntryRecommendBinList", body)
            result["tests"]["warehouse_bin"] = first_summary | {"candidate_join": "real_wid_product_id_fnsku_values"}
            if first_summary.get("code") == "2001006":
                variants = [
                    {"list": [{"wid": wid_pairs[0][1], "productId": product_pairs[0][1], "fnsku": fnsku_pairs[0][1]}]},
                    {"list": [{"wid": wid_pairs[0][1], "productId": product_pairs[0][1], "fnsku": fnsku_pairs[0][1], "sid": 12134}], "withHistory": True},
                ]
                result["tests"]["warehouse_bin_variants"] = [(await call("/basicOpen/warehouseConfig/warehouseBin/getEntryRecommendBinList", variant))[0] for variant in variants]
        else:
            result["tests"]["warehouse_bin"] = {"category": "missing_joined_wid_product_id_fnsku", "wid": len(wid_pairs), "product_id": len(product_pairs), "fnsku": len(fnsku_pairs)}
    finally:
        await client.close()
    print(json.dumps(result, ensure_ascii=False, sort_keys=True))


asyncio.run(main())
